// این فایل به‌صورت خودکار از فایل‌های ورد پرسشنامه استخراج و ساخته شده است.
// منابع: پرسشنامه_توانیر.docx | پرسشنامه_گلخانه...docx | پرسشنامه_مرغداری...docx

// -----------------------------
// تایپ‌ها (Types)
// -----------------------------

/** صنعت اصلی */
export type Industry = "energy" | "agriculture";

/** زیربخش هر صنعت. توانیر زیرمجموعه انرژی است، گلخانه و مرغداری زیرمجموعه کشاورزی هستند. */
export type Sector = "tavanir" | "greenhouse" | "poultry";

export interface ScoringCriterion {
  score: 1 | 2 | 3 | 4 | 5;
  description: string;
}

/** یک سوال؛ متعلق به یک مؤلفه و یک شاخص، در یک بعد مشخص */
export interface Question {
  /** شناسه یکتا، مثل tavanir-d1-01 */
  id: string;
  /** مؤلفه (component) - سطح گروه‌بندی بالاتر شاخص */
  component: string;
  /** شاخص (indicator) - زیرمجموعه مؤلفه که این سوال برای سنجش آن طراحی شده */
  indicator: string;
  /**
   * پرسش عمومی صنعت - فقط برای گلخانه و مرغداری وجود دارد (بخش کشاورزی).
   * توانیر (انرژی) فقط پرسش اختصاصی دارد و این فیلد را ندارد.
   */
  generalQuestion?: string;
  /** پرسش اختصاصی مربوط به همان زیربخش (توانیر/گلخانه/مرغداری) */
  specificQuestion: string;
  /** ۵ سطح معیار امتیازدهی، از ۱ (ضعیف‌ترین) تا ۵ (بهترین) */
  scoringCriteria: ScoringCriterion[];
}

/** یک بعد (dimension) از ۷ بعد ارزیابی، شامل چند سوال */
export interface Dimension {
  /** شناسه یکتا، مثل dim1 */
  id: string;
  /** شماره ترتیب بعد (۱ تا ۷) */
  order: number;
  /** عنوان بعد */
  title: string;
  questions: Question[];
}

/** پرسشنامه کامل یک زیربخش (توانیر یا گلخانه یا مرغداری) */
export interface SectorQuestionnaire {
  sector: Sector;
  industry: Industry;
  /** عنوان کامل پرسشنامه */
  title: string;
  dimensions: Dimension[];
}

