// -----------------------------
// نگاشت صنعت به زیربخش‌ها (کمکی برای UI)
// -----------------------------

export const industrySectors: Record<Industry, Sector[]> = {
  agriculture: ["greenhouse", "poultry"],
  energy: ["tavanir"],
};

// -----------------------------
// توابع کمکی (Helpers)
// -----------------------------

export function getQuestionnaire(sector: Sector): SectorQuestionnaire {
  return questionnaires[sector];
}

export function getAllQuestions(sector: Sector): Question[] {
  return questionnaires[sector].dimensions.flatMap((d) => d.questions);
}

export function getDimension(
  sector: Sector,
  dimensionId: string,
): Dimension | undefined {
  return questionnaires[sector].dimensions.find((d) => d.id === dimensionId);
}

export function getScoringCriterion(
  question: Question,
  score: 1 | 2 | 3 | 4 | 5,
): ScoringCriterion | undefined {
  return question.scoringCriteria.find((c) => c.score === score);
}
